*{box-sizing:border-box} :root{--ink:#e7e6d9;--muted:#8c9688;--dim:#586356;--line:rgba(207,215,195,.12);--panel:#151b16;--deep:#101611;--lime:#c0d48a;--amber:#ddb979;--red:#cf7664} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#0e140f;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game-shell{height:100dvh;min-height:540px;display:grid;grid-template-rows:58px minmax(0,1fr) 92px;background:var(--deep)}.topbar{height:58px;display:flex;align-items:center;padding:0 24px;border-bottom:1px solid var(--line);background:#121813;z-index:3;gap:32px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#edf0e3;font-family:Oswald,sans-serif;font-size:17px;font-weight:500;letter-spacing:1.9px;min-width:176px}.brand-mark{width:26px;height:26px;display:grid;place-items:center;border:1px solid #879576;color:#c5d294;font-size:17px;font-family:serif;transform:rotate(45deg);line-height:1}.brand-mark::first-letter{transform:rotate(-45deg)}.brand-light{color:#879576}.world-meta{display:flex;align-items:center;gap:9px;font:10px 'DM Mono',monospace;letter-spacing:1.2px;color:#aab1a1}.live-dot{height:6px;width:6px;border-radius:50%;background:#c2d48b;box-shadow:0 0 8px #c2d48b88}.meta-divider{height:13px;width:1px;background:var(--line);margin:0 5px}.top-actions{margin-left:auto;display:flex;gap:9px}.icon-button{height:34px;padding:0 11px;background:transparent;border:1px solid var(--line);border-radius:3px;color:#bec6b6;font:16px 'DM Mono',monospace;cursor:pointer;transition:.18s}.icon-button span{font:9px 'DM Mono',monospace;letter-spacing:1px;margin-left:5px}.icon-button:hover{border-color:#a6b27f;color:#e3e8d6;background:#c0d48a0d}.play-area{position:relative;overflow:hidden;background:#29392b;min-height:0}canvas{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 48% 48%,transparent 42%,rgba(9,14,10,.16) 100%),linear-gradient(180deg,rgba(8,12,9,.19),transparent 16%,transparent 78%,rgba(8,12,9,.24)}.location-card{position:absolute;top:20px;left:22px;display:flex;align-items:center;gap:11px;padding:10px 13px;background:rgba(16,22,17,.78);border:1px solid rgba(220,225,209,.16);backdrop-filter:blur(8px);border-radius:3px}.location-icon{color:#d0d39a;font-size:23px}.eyebrow,.location-distance{font:9px 'DM Mono',monospace;letter-spacing:1.15px;color:#9da697}.location-card strong{display:block;margin-top:3px;font-family:Oswald,sans-serif;font-size:15px;font-weight:400;letter-spacing:.5px}.location-distance{border-left:1px solid var(--line);padding-left:12px;margin-left:6px;font-size:8px}.weather-chip{position:absolute;top:21px;right:22px;display:flex;align-items:center;gap:8px;color:#d9ddc9;background:#101611a8;padding:8px 11px;border:1px solid #d5dcc51b;border-radius:2px;font:9px 'DM Mono',monospace;letter-spacing:1px}.weather-chip span:first-child{font-size:16px;color:#d4cb97}.day-clock{position:absolute;top:74px;right:25px;display:flex;align-items:center;gap:8px;text-align:right}.sun-icon{font-size:20px;color:#d6bf7d}.day-clock strong{display:block;font:16px 'DM Mono',monospace;letter-spacing:1px}.day-clock small{display:block;font:8px 'DM Mono',monospace;letter-spacing:1.5px;color:#b8c0ae;margin-top:2px}.compass{position:absolute;left:50%;top:20px;transform:translateX(-50%);display:flex;align-items:center;gap:7px;color:#e2e4d7;font:9px 'DM Mono',monospace;opacity:.8;text-shadow:0 1px 3px #000}.compass i{font-style:normal;color:#a9b39d}.compass-tick{position:absolute;top:-9px;left:50%;height:6px;width:1px;background:#d3d9c4}.compass-needle{position:absolute;top:14px;left:50%;width:0;height:0;border-left:3px solid transparent;border-right:3px solid transparent;border-bottom:7px solid #df795f}.objective{position:absolute;bottom:22px;left:22px;display:flex;align-items:center;gap:10px;padding:10px 12px;background:rgba(17,23,17,.83);border:1px solid rgba(213,221,198,.17);backdrop-filter:blur(8px);border-radius:3px;min-width:220px}.objective-pin{font-size:17px;color:#d5c682}.objective div{display:grid;gap:3px}.objective small{font:8px 'DM Mono',monospace;letter-spacing:1.1px;color:#9ba38f}.objective div span{font-size:11px;color:#d9ddcf}.objective button{margin-left:auto;border:0;background:none;color:#9ba38f;font-size:19px;cursor:pointer}.bottom-hint{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);padding:8px 12px;background:rgba(17,23,17,.72);border:1px solid rgba(213,221,198,.14);color:#afb6a6;font:8px 'DM Mono',monospace;letter-spacing:.8px;white-space:nowrap}.bottom-hint kbd{font:9px 'DM Mono',monospace;color:#e3e6d9;border:1px solid #d5dcc52b;border-radius:2px;padding:2px 4px;margin:0 3px 0 7px}.toast{position:absolute;left:50%;top:22%;transform:translate(-50%,-8px);padding:9px 16px;background:#111913e8;border:1px solid #d6dcbd3d;color:#e7e8d9;font:10px 'DM Mono',monospace;letter-spacing:.5px;opacity:0;transition:.25s;pointer-events:none;z-index:2}.toast.show{opacity:1;transform:translate(-50%,0)}.prompt{position:absolute;left:50%;bottom:22%;transform:translateX(-50%);padding:8px 12px;background:#101611d9;border:1px solid #d4d9c331;color:#e7e9dc;font:10px 'DM Mono',monospace;letter-spacing:.5px;opacity:0;transition:.15s;pointer-events:none;white-space:nowrap}.prompt.visible{opacity:1}.prompt kbd{display:inline-grid;place-items:center;padding:2px 5px;border:1px solid #d2d9c430;border-radius:2px;margin-right:6px;color:#e0d39e}.threat-indicator{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font:9px 'DM Mono',monospace;letter-spacing:2px;color:#ec9a82;opacity:0;transition:.25s;pointer-events:none;text-shadow:0 1px 8px #000}.threat-indicator.active{opacity:1}.threat-pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:#e78370;margin-right:7px;box-shadow:0 0 12px #ec715b;animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.35}}.status-bar{height:92px;background:#141a15;border-top:1px solid var(--line);display:flex;align-items:center;padding:0 23px;gap:25px;z-index:2}.survivor-card{display:flex;align-items:center;gap:10px;min-width:229px}.avatar{height:37px;width:37px;border:1px solid #8b9874;border-radius:50%;display:grid;place-items:center;color:#c3d18c;font-size:21px;position:relative}.avatar-status{height:7px;width:7px;border-radius:50%;background:#a6c379;position:absolute;right:0;bottom:1px;border:1px solid #141a15}.survivor-name{display:grid;gap:4px;min-width:84px}.survivor-name strong{font:12px Oswald,sans-serif;letter-spacing:1.1px;font-weight:400}.survivor-name small{font:8px 'DM Mono',monospace;letter-spacing:.6px;color:#a3ab9c}.health-wrap{width:85px;margin-left:3px}.health-label,.need-top{display:flex;justify-content:space-between;align-items:center;font:8px 'DM Mono',monospace;letter-spacing:.7px;color:#9fa798}.health-label b{color:#d8dfce;font-weight:400}.health-track,.need-track{height:3px;background:#394239;margin-top:6px;overflow:hidden;border-radius:3px}.health-track i,.need-track i{height:100%;width:100%;display:block;background:#9eb974;transition:width .3s}.need{width:117px;flex-shrink:0}.need-top{gap:5px}.need-top b{margin-left:auto;color:#d8dfce;font-weight:400}.need-icon{font-size:12px;color:#b9c68a;margin-right:2px}.need-track i{background:#a6b77c}.need[data-need=water] .need-track i{background:#7fa8aa}.need[data-need=temp] .need-track i{background:#d2ae6b}.stamina-track i{background:#839988}.quick-slots{margin-left:auto;min-width:140px}.slots-head{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:.9px;color:#a0a999;margin-bottom:7px}.slots-head span:last-child{color:#697565}.slot-row{display:flex;gap:5px}.quick-slot{width:43px;height:35px;background:#1a221a;border:1px solid #d5ddc521;position:relative;display:grid;place-items:center;border-radius:2px;cursor:pointer}.quick-slot:hover{border-color:#a8b67e}.quick-slot kbd{position:absolute;left:4px;top:3px;font:8px 'DM Mono',monospace;color:#818b7e}.slot-item{font-size:9px;color:#d4d8c8;max-width:38px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.overlay{position:fixed;inset:0;z-index:10;background:#090e0bc9;backdrop-filter:blur(5px);display:grid;place-items:center;padding:22px}.overlay[hidden]{display:none}.modal{width:min(720px,94vw);max-height:88dvh;overflow:auto;background:#151c16;border:1px solid #d0d8c32c;box-shadow:0 22px 80px #0009;padding:26px 30px 28px;position:relative}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:20px}.modal-kicker{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#9fac89}.modal h2{font:25px Oswald,sans-serif;letter-spacing:1px;font-weight:400;margin:5px 0 0}.close-modal{background:none;border:1px solid var(--line);color:#aab2a4;width:29px;height:29px;cursor:pointer;font-size:18px}.inventory-layout{display:grid;grid-template-columns:1.15fr .85fr;gap:24px}.section-title{font:9px 'DM Mono',monospace;letter-spacing:1.3px;color:#a8b29d;margin:0 0 10px}.inventory-list{display:grid;gap:7px}.item-row{display:flex;align-items:center;padding:9px 10px;background:#1b241c;border:1px solid #d0d9c217;gap:9px;min-height:48px}.item-symbol{width:27px;height:27px;display:grid;place-items:center;background:#2c3729;color:#c7d397;font-size:15px}.item-info{flex:1}.item-info strong{display:block;font-size:11px;font-weight:500}.item-info small{display:block;font:8px 'DM Mono',monospace;color:#929b8d;margin-top:3px}.item-weight{font:8px 'DM Mono',monospace;color:#949d8c}.item-action{border:1px solid #d0d9c22b;background:#222d22;padding:6px 8px;font:8px 'DM Mono',monospace;letter-spacing:.5px;cursor:pointer}.item-action:hover{border-color:#a6b77e;color:#d7e2bb}.item-action:disabled{opacity:.35;cursor:not-allowed}.inventory-summary{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#a7b09d;padding:11px 0;border-bottom:1px solid var(--line);margin-bottom:17px}.inventory-summary b{color:#e2e5d7;font-weight:400}.empty-state{padding:22px 12px;border:1px dashed #d1d8c126;text-align:center;color:#9ca694;font-size:11px;line-height:1.8}.craft-card{padding:12px;background:#1a231b;border:1px solid #cfd8c11f;margin-bottom:9px}.craft-card strong{font-size:11px;font-weight:500}.craft-card p{font-size:9px;line-height:1.5;color:#98a191;margin:5px 0 10px}.craft-card button,.modal-primary{padding:8px 11px;border:1px solid #aebc7a6b;background:#aebc7a16;color:#d8e1be;font:9px 'DM Mono',monospace;letter-spacing:.5px;cursor:pointer}.craft-card button:hover,.modal-primary:hover{background:#b3c7812a}.craft-card button:disabled{opacity:.38;cursor:not-allowed}.craft-note{font:8px 'DM Mono',monospace;color:#737e6f;margin-top:12px;line-height:1.7}.map-content{display:grid;grid-template-columns:minmax(0,1fr) 185px;gap:20px}.map-canvas-wrap{aspect-ratio:1;background:#27382a;border:1px solid #d2dcc421;position:relative;overflow:hidden}.map-canvas-wrap canvas{width:100%;height:100%}.map-legend{font:9px 'DM Mono',monospace;color:#aab2a2;line-height:2.2}.legend-row{display:flex;gap:8px;align-items:center}.legend-dot{width:7px;height:7px;border-radius:50%;background:#c39b69}.legend-dot.green{background:#899b70}.legend-dot.red{background:#d27360}.map-blurb{font-size:10px;line-height:1.7;color:#9ca595;margin-top:14px}.controls-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.control-row{padding:11px 12px;background:#1a231b;border:1px solid #d1d8c218;font-size:10px;color:#b8c0af;display:flex;justify-content:space-between;gap:12px}.control-row kbd{font:9px 'DM Mono',monospace;color:#e5e5d8;border:1px solid #d2dac22d;padding:3px 5px;white-space:nowrap}.modal-foot{font-size:9px;color:#838e7f;line-height:1.7;margin-top:17px}.mobile-controls{display:none}.game-over{position:fixed;inset:0;z-index:20;background:#0b100de8;display:grid;place-items:center;text-align:center}.game-over h1{font:48px Oswald,sans-serif;letter-spacing:5px;font-weight:400;color:#d8ddca;margin:0}.game-over p{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#9da594;margin:14px 0 25px}.game-over button{padding:11px 19px;background:#afbf7d17;border:1px solid #afbf7d7a;color:#dbe3c2;font:10px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}
@media(max-width:1000px){.status-bar{gap:14px;padding:0 15px}.survivor-card{min-width:194px}.need{width:100px}.health-wrap{width:64px}.topbar{padding:0 16px}.bottom-hint{display:none}}@media(max-width:700px){.game-shell{grid-template-rows:50px minmax(0,1fr) 112px;min-height:450px}.topbar{height:50px;padding:0 12px;gap:10px}.brand{min-width:0;font-size:15px;letter-spacing:1px;gap:7px}.brand-mark{height:22px;width:22px;font-size:14px}.world-meta{margin-left:auto;font-size:8px;letter-spacing:.5px;gap:6px}.meta-divider,.world-meta #weatherLabel{display:none}.top-actions{margin-left:2px;gap:5px}.icon-button{height:30px;width:31px;padding:0;font-size:14px}.icon-button span{display:none}.location-card{top:12px;left:11px;padding:7px 9px;gap:7px}.location-icon{font-size:19px}.eyebrow,.location-distance{font-size:7px}.location-card strong{font-size:13px}.location-distance{padding-left:7px;margin-left:2px}.weather-chip{top:12px;right:11px;padding:6px 7px;font-size:7px}.weather-chip span:first-child{font-size:13px}.day-clock{top:53px;right:13px;gap:5px}.sun-icon{font-size:15px}.day-clock strong{font-size:13px}.day-clock small{font-size:7px}.compass{top:15px;font-size:7px;gap:4px}.objective{left:10px;bottom:12px;min-width:0;padding:7px 9px;gap:7px}.objective-pin{font-size:14px}.objective small{font-size:7px}.objective div span{font-size:9px}.objective button{font-size:16px}.threat-indicator{top:39%;font-size:8px}.prompt{bottom:29%;font-size:8px}.status-bar{height:112px;padding:9px 12px;display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:42px 38px;gap:5px 10px}.survivor-card{min-width:0;grid-column:1/3;gap:7px}.avatar{width:30px;height:30px;font-size:17px}.survivor-name{gap:2px}.survivor-name strong{font-size:10px}.survivor-name small{font-size:7px}.health-wrap{width:auto;flex:1;margin-left:4px}.need{width:auto;align-self:center}.need-top{font-size:7px;gap:3px}.need-icon{font-size:10px}.need-track{margin-top:4px}.stamina-need{display:none}.quick-slots{grid-column:3;grid-row:1/3;min-width:0;align-self:center;margin:0}.slots-head{font-size:7px}.slot-row{gap:3px}.quick-slot{width:32px;height:31px}.quick-slot kbd{font-size:7px;left:3px;top:2px}.slot-item{font-size:7px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.joystick{position:absolute;left:23px;bottom:67px;width:104px;height:104px;border-radius:50%;border:1px solid #dbe1cb3d;background:#131a1670;pointer-events:auto;touch-action:none}.joystick:after{content:'';position:absolute;inset:20px;border-radius:50%;border:1px solid #dbe1cb1a}.joy-knob{position:absolute;left:50%;top:50%;width:39px;height:39px;margin:-19.5px;border-radius:50%;background:#c1cd9b36;border:1px solid #dbe1cb52;z-index:1}.mobile-action-stack{position:absolute;right:18px;bottom:66px;display:flex;gap:12px;align-items:flex-end;pointer-events:auto}.mobile-action-stack button{height:52px;width:52px;border-radius:50%;border:1px solid #dbe1cb59;background:#151d16b8;color:#e0e5d3;font-size:19px;touch-action:manipulation}.mobile-action-stack button small{display:block;font:7px 'DM Mono',monospace;color:#c1c9b5}.mobile-action-stack .attack-button{height:60px;width:60px;color:#e79b84;border-color:#e090784d}.map-content{grid-template-columns:1fr}.map-legend{display:grid;grid-template-columns:1fr 1fr;line-height:1.8}.map-blurb{grid-column:1/-1;margin-top:4px}.modal{padding:20px 17px}.modal h2{font-size:22px}.inventory-layout{grid-template-columns:1fr}.modal{max-height:90dvh}.modal-foot{margin-top:10px}.controls-grid{grid-template-columns:1fr}.location-card{max-width:65%}}
