(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const WORLD=2600, TAU=Math.PI*2;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let seed=92841;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const choose=a=>a[Math.floor(rand()*a.length)];
let dpr=1,w=0,h=0,last=0,gameTime=8.4,elapsed=0,weather='CLEAR',weatherClock=0,toastTimer=0,overlayType='',gameOver=false;
const player={x:1320,y:1350,r:9,speed:122,health:100,food:82,water:74,temp:36.8,stamina:100,energy:100,blood:100,attack:0,invuln:0,dir:0};
const camera={x:player.x,y:player.y};
const inventory=[];let capacity=24;
const items={"Canned beans":{type:'food',weight:1,icon:'◍',value:29,loot:'home'},"Purified water":{type:'water',weight:1,icon:'◉',value:35,loot:'home'},"Bandage":{type:'medical',weight:.3,icon:'＋',value:22,loot:'medical'},"Antibiotics":{type:'medical',weight:.2,icon:'✚',value:40,loot:'medical'},"Trail mix":{type:'food',weight:.4,icon:'◒',value:18,loot:'forest'},"Dried meat":{type:'food',weight:.6,icon:'▰',value:24,loot:'forest'},"Bottle of water":{type:'water',weight:1,icon:'◉',value:25,loot:'forest'},"Wood scrap":{type:'material',weight:1.5,icon:'▤',loot:'any'},"Rag":{type:'material',weight:.2,icon:'▱',loot:'any'},"Scrap metal":{type:'material',weight:2,icon:'▧',loot:'industrial'},"Flashlight":{type:'tool',weight:.7,icon:'⌁',loot:'home'},"Pocket knife":{type:'weapon',weight:.5,icon:'⌁',damage:26,loot:'home'},"Old revolver":{type:'weapon',weight:1.2,icon:'⌖',damage:40,loot:'police'},"Ammo (6)":{type:'ammo',weight:.3,icon:'▪',loot:'police'},"Warm jacket":{type:'clothing',weight:1.4,icon:'◈',loot:'home'}};
let buildings=[],trees=[],loot=[],zombies=[],decor=[],roads=[],waterAreas=[],particles=[],effects=[];
const keys={};let joy={x:0,y:0,active:false};
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
window.addEventListener('resize',resize);resize();
function makeWorld(){
  // procedural woodland, roads, homestead and remote landmarks
  const regions=[{x:1320,y:1320,name:'Pine Ridge',type:'hamlet'},{x:620,y:560,name:'Marlow Farm',type:'farm'},{x:2050,y:610,name:'Pine Ridge Clinic',type:'clinic'},{x:2020,y:1980,name:'Old Mill',type:'mill'},{x:530,y:2070,name:'Ashwood Camp',type:'camp'}];
  roads=[[[1320,1320],[1100,1120],[970,900],[850,730],[620,560]],[[1320,1320],[1510,1120],[1710,900],[1890,770],[2050,610]],[[1320,1320],[1510,1510],[1690,1690],[1850,1850],[2020,1980]],[[1320,1320],[1100,1540],[900,1760],[720,1940],[530,2070]],[[1320,1320],[1330,1080],[1360,820],[1400,580]],[[1320,1320],[1320,1570],[1300,1840],[1260,2110]]];
  waterAreas=[{x:2300,y:1500,rx:250,ry:420},{x:300,y:1220,rx:110,ry:260},{x:1000,y:2350,rx:330,ry:100}];
  const addBuilding=(x,y,type,angle=0)=>buildings.push({x,y,type,angle,w:type==='barn'?88:type==='clinic'?100:66,h:type==='barn'?56:type==='clinic'?66:54,loot:[],name:type==='clinic'?'Clinic':type==='store'?'General Store':type==='barn'?'Farmhouse':choose(['Abandoned home','Ranger cabin','Ruined cottage'])});
  for(const reg of regions){
    const count=reg.type==='hamlet'?9:reg.type==='clinic'?4:reg.type==='farm'?6:5;
    for(let i=0;i<count;i++){const a=rand()*TAU,r=reg.type==='hamlet'?40+rand()*125:35+rand()*100;const x=reg.x+Math.cos(a)*r,y=reg.y+Math.sin(a)*r;let type=reg.type==='clinic'?'clinic':reg.type==='farm'?(i===0?'barn':'home'):reg.type==='mill'?(i===0?'mill':'home'):reg.type==='camp'?'cabin':(i===0?'store':'home');addBuilding(x,y,type,rand()*0.16-.08)}
  }
  // cross-country rocks and tree cover, with clear lanes around structures and roads
