function openModal(type){overlayType=type;$('overlay').hidden=false;renderOverlay()}
function closeModal(){$('overlay').hidden=true;overlayType='';canvas.focus()}
function modalHead(title,sub){return `<header class="modal-head"><div><div class="modal-kicker">${sub}</div><h2>${title}</h2></div><button class="close-modal" data-close aria-label="Close">×</button></header>`}
const crafts=[{name:'Field Campfire',desc:'A small fire for warmth. Rest nearby to recover health.',cost:{'Wood scrap':3,'Rag':1},type:'fire',icon:'♨'},{name:'Lean-to Shelter',desc:'A dry place to recover energy and slowly heal.',cost:{'Wood scrap':5,'Rag':2},type:'shelter',icon:'⌂'},{name:'Rough Barricade',desc:'A defensive marker for your camp. Keep infected at a distance.',cost:{'Wood scrap':4,'Scrap metal':2},type:'barricade',icon:'▥'}];
function canCraft(c){return Object.entries(c.cost).every(([n,q])=>countItem(n)>=q)}
function craft(c){if(!canCraft(c)){toast('MISSING MATERIALS');return}for(const [n,q]of Object.entries(c.cost))removeItem(n,q);const o={x:player.x+Math.cos(player.dir)*27,y:player.y+Math.sin(player.dir)*27,type:c.type};campObjects.push(o);toast('BUILT · '+c.name.toUpperCase());renderOverlay()}
function renderOverlay(){if(!overlayType)return;const modal=$('modal');if(overlayType==='inventory'){
 const total=weight();const rows=inventory.map((it,i)=>{const d=items[it.name]||{};const usable=['food','water','medical','weapon','tool'].includes(d.type);const action=d.type==='weapon'?'EQUIP / USE':usable?'USE':'DROP';return `<div class="item-row"><span class="item-symbol">${d.icon||'◈'}</span><div class="item-info"><strong>${it.name}${it.qty>1?' ×'+it.qty:''}</strong><small>${(d.type||'supplies').toUpperCase()} · ${d.weight||1} KG EACH</small></div><span class="item-weight">${((d.weight||1)*it.qty).toFixed(1)} KG</span><button class="item-action" data-item="${it.name}" data-action="${d.type==='weapon'?'use':usable?'use':'drop'}">${action}</button></div>`}).join('');
 modal.innerHTML=modalHead('Field pack','CARRYING YOUR LIFE')+`<div class="inventory-layout"><div><div class="inventory-summary"><span>PACK LOAD</span><b>${total.toFixed(1)} / ${capacity} KG</b></div><h3 class="section-title">CARRIED ITEMS</h3><div class="inventory-list">${rows||'<div class="empty-state">Your pack is empty.<br>Look around buildings and trails for supplies.</div>'}</div></div><div><h3 class="section-title">FIELD CRAFTING</h3>${crafts.map(c=>`<div class="craft-card"><strong>${c.icon} &nbsp;${c.name}</strong><p>${c.desc}<br>Requires ${Object.entries(c.cost).map(([n,q])=>`${q} ${n}`).join(' · ')}</p><button data-craft="${c.name}" ${canCraft(c)?'':'disabled'}>BUILD AT YOUR FEET</button></div>`).join('')}<div class="craft-note">SHELTERS ARE A PLACE TO REST. CAMPFIRES KEEP THE COLD OFF. CRAFTING TAKES THE MATERIALS IN YOUR PACK.</div></div></div>`;
 }else if(overlayType==='map'){
 modal.innerHTML=modalHead('The Cascade','FIELD MAP · APPROXIMATE')+`<div class="map-content"><div class="map-canvas-wrap"><canvas id="mapCanvas" width="500" height="500"></canvas></div><div class="map-legend"><div class="section-title">LANDMARKS</div><div class="legend-row"><i class="legend-dot"></i> Settlement</div><div class="legend-row"><i class="legend-dot green"></i> Woods / camp</div><div class="legend-row"><i class="legend-dot red"></i> Infected</div><div class="legend-row"><span style="color:#e6dfbb;font-size:13px">▲</span> You are here</div><div class="map-blurb">A rough sketch of North Cascade. Trails link the settlements. The marked roads are not necessarily safe.<br><br><span style="color:#d8d5b9">CLICK THE MAP</span> to place a field marker.</div></div></div>`;drawMap();
 }else{
 modal.innerHTML=modalHead('Stay alive','FIELD GUIDE')+`<div class="controls-grid"><div class="control-row"><span>Move through the world</span><kbd>W A S D</kbd></div><div class="control-row"><span>Sprint (uses stamina)</span><kbd>SHIFT</kbd></div><div class="control-row"><span>Pick up / search</span><kbd>E</kbd></div><div class="control-row"><span>Melee attack</span><kbd>SPACE</kbd></div><div class="control-row"><span>Use quick item</span><kbd>1 — 3</kbd></div><div class="control-row"><span>Open field map</span><kbd>M</kbd></div><div class="control-row"><span>Open field pack</span><kbd>I / TAB</kbd></div><div class="control-row"><span>Close any screen</span><kbd>ESC</kbd></div></div><p class="modal-foot">The infected hear a sprint, and gunfire carries a long way. Keep hunger and thirst above empty; find medical supplies if you take a hit. Explore homes, the clinic, farms and the old mill. Craft a fire or shelter from your field pack. The world keeps moving while you survive.</p>`
 }
}
function drawMap(){const c=$('mapCanvas');if(!c)return;const m=c.getContext('2d'),s=c.width/WORLD;m.fillStyle='#455a43';m.fillRect(0,0,c.width,c.height);for(let i=0;i<1400;i++){const x=rand()*c.width,y=rand()*c.height;m.fillStyle=i%3?'#71805b30':'#283a2a3c';m.fillRect(x,y,1+rand()*2,1)}for(const a of waterAreas){m.fillStyle='#3b6b65';m.beginPath();m.ellipse(a.x*s,a.y*s,a.rx*s,a.ry*s,0,0,TAU);m.fill()}for(const line of roads){m.beginPath();line.forEach((v,i)=>i?m.lineTo(v[0]*s,v[1]*s):m.moveTo(v[0]*s,v[1]*s));m.strokeStyle='#c2b58a';m.lineWidth=2;m.stroke()}for(const r of regions){m.fillStyle=r.type==='camp'?'#9aa97a':'#c39d6c';m.beginPath();m.arc(r.x*s,r.y*s,5,0,TAU);m.fill();m.font='9px monospace';m.fillStyle='#e2e4d3';m.fillText(r.name,r.x*s+7,r.y*s-6)}for(const z of zombies){m.fillStyle='#d27360';m.beginPath();m.arc(z.x*s,z.y*s,2.1,0,TAU);m.fill()}m.fillStyle='#e8e4bc';m.beginPath();m.moveTo(player.x*s,(player.y-10)*s);m.lineTo((player.x+7)*s,(player.y+6)*s);m.lineTo((player.x-7)*s,(player.y+6)*s);m.closePath();m.fill();m.strokeStyle='#e8e4bc88';m.beginPath();m.arc(player.x*s,player.y*s,36,0,TAU);m.stroke();if(fieldMarker){m.strokeStyle='#ead584';m.lineWidth=2;m.beginPath();m.arc(fieldMarker.x*s,fieldMarker.y*s,7,0,TAU);m.stroke();m.fillStyle='#ead584';m.fillRect(fieldMarker.x*s-1,fieldMarker.y*s-10,2,6)}}
let fieldMarker=null;

