(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const WORLD=2600,TAU=Math.PI*2,clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let seed=92841;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296},choose=a=>a[Math.floor(rand()*a.length)];
let dpr=1,w=0,h=0,last=0,gameTime=8.4,elapsed=0,weather='CLEAR',weatherClock=0,toastTimer=0,overlayType='',gameOver=false,fieldMarker=null;
const player={x:1320,y:1350,r:9,speed:122,health:100,food:82,water:74,temp:36.8,stamina:100,energy:100,blood:100,attack:0,invuln:0,dir:0};
const camera={x:player.x,y:player.y},inventory=[];let capacity=24;
const items={"Canned beans":{type:'food',weight:1,icon:'◍',value:29,loot:'home'},"Purified water":{type:'water',weight:1,icon:'◉',value:35,loot:'home'},"Bandage":{type:'medical',weight:.3,icon:'＋',value:22,loot:'medical'},"Antibiotics":{type:'medical',weight:.2,icon:'✚',value:40,loot:'medical'},"Trail mix":{type:'food',weight:.4,icon:'◒',value:18,loot:'forest'},"Dried meat":{type:'food',weight:.6,icon:'▰',value:24,loot:'forest'},"Bottle of water":{type:'water',weight:1,icon:'◉',value:25,loot:'forest'},"Wood scrap":{type:'material',weight:1.5,icon:'▤',loot:'any'},"Rag":{type:'material',weight:.2,icon:'▱',loot:'any'},"Scrap metal":{type:'material',weight:2,icon:'▧',loot:'industrial'},"Flashlight":{type:'tool',weight:.7,icon:'⌁',loot:'home'},"Pocket knife":{type:'weapon',weight:.5,icon:'⌁',damage:26,loot:'home'},"Old revolver":{type:'weapon',weight:1.2,icon:'⌖',damage:40,loot:'police'},"Ammo (6)":{type:'ammo',weight:.3,icon:'▪',loot:'police'},"Warm jacket":{type:'clothing',weight:1.4,icon:'◈',loot:'home'}};
let buildings=[],trees=[],loot=[],zombies=[],decor=[],roads=[],waterAreas=[],campObjects=[];const keys={};let joy={x:0,y:0,active:false},movingSprint=false;const quickItems=['Trail mix','Purified water','Bandage'];
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function makeWorld(){
 const regions=[{x:1320,y:1320,name:'Pine Ridge',type:'hamlet'},{x:620,y:560,name:'Marlow Farm',type:'farm'},{x:2050,y:610,name:'Pine Ridge Clinic',type:'clinic'},{x:2020,y:1980,name:'Old Mill',type:'mill'},{x:530,y:2070,name:'Ashwood Camp',type:'camp'}];
 roads=[[[1320,1320],[1100,1120],[970,900],[850,730],[620,560]],[[1320,1320],[1510,1120],[1710,900],[1890,770],[2050,610]],[[1320,1320],[1510,1510],[1690,1690],[1850,1850],[2020,1980]],[[1320,1320],[1100,1540],[900,1760],[720,1940],[530,2070]],[[1320,1320],[1330,1080],[1360,820],[1400,580]],[[1320,1320],[1320,1570],[1300,1840],[1260,2110]]];
 waterAreas=[{x:2300,y:1500,rx:250,ry:420},{x:300,y:1220,rx:110,ry:260},{x:1000,y:2350,rx:330,ry:100}];
 const addBuilding=(x,y,type,angle=0)=>buildings.push({x,y,type,angle,w:type==='barn'?88:type==='clinic'?100:66,h:type==='barn'?56:type==='clinic'?66:54,loot:[],name:type==='clinic'?'Clinic':type==='store'?'General Store':type==='barn'?'Farmhouse':choose(['Abandoned home','Ranger cabin','Ruined cottage'])});
 for(const reg of regions){const count=reg.type==='hamlet'?9:reg.type==='clinic'?4:reg.type==='farm'?6:5;for(let i=0;i<count;i++){const a=rand()*TAU,r=reg.type==='hamlet'?40+rand()*125:35+rand()*100,x=reg.x+Math.cos(a)*r,y=reg.y+Math.sin(a)*r;let type=reg.type==='clinic'?'clinic':reg.type==='farm'?(i===0?'barn':'home'):reg.type==='mill'?(i===0?'mill':'home'):reg.type==='camp'?'cabin':(i===0?'store':'home');addBuilding(x,y,type,rand()*.16-.08)}}
 for(let i=0;i<690;i++){let x=rand()*WORLD,y=rand()*WORLD;if(waterAreas.some(a=>((x-a.x)/a.rx)**2+((y-a.y)/a.ry)**2<1))continue;if(buildings.some(b=>Math.abs(x-b.x)<b.w*.8&&Math.abs(y-b.y)<b.h*.8))continue;trees.push({x,y,r:9+rand()*12,t:rand(),shade:rand()})}
 for(let i=0;i<70;i++){let x=rand()*WORLD,y=rand()*WORLD;if(!waterAreas.some(a=>((x-a.x)/a.rx)**2+((y-a.y)/a.ry)**2<1))decor.push({x,y,type:rand()<.5?'stone':'grass',r:2+rand()*5})}
 for(const b of buildings){const category=b.type==='clinic'?'medical':b.type==='mill'?'industrial':b.type==='store'?'home':b.type==='barn'?'farm':b.type==='cabin'?'forest':'home',n=b.type==='clinic'?4:b.type==='store'?4:2;for(let i=0;i<n;i++){let pool=Object.keys(items).filter(k=>items[k].loot===category||items[k].loot==='any'),name=choose(pool);loot.push({x:b.x+(rand()-.5)*b.w*.7,y:b.y+(rand()-.5)*b.h*.7,name,active:true,source:b})}}
 for(let i=0;i<58;i++){let x=rand()*WORLD,y=rand()*WORLD;if(buildings.some(b=>dist({x,y},b)<95))continue;loot.push({x,y,name:choose(['Trail mix','Dried meat','Bottle of water','Wood scrap','Rag']),active:true})}for(let i=0;i<17;i++){let x=rand()*WORLD,y=rand()*WORLD;if(!buildings.some(b=>dist({x,y},b)<95))loot.push({x,y,name:'Wood scrap',active:true})}
 for(const reg of regions)for(let i=0;i<(reg.type==='hamlet'?7:4);i++){let a=rand()*TAU,r=100+rand()*170;zombies.push({x:reg.x+Math.cos(a)*r,y:reg.y+Math.sin(a)*r,r:8+rand()*2,type:rand()<.2?'runner':'infected',hp:rand()<.18?3:2,state:'wander',dir:rand()*TAU,speed:rand()<.2?52:29,attack:0,stun:0,wander:0,alert:0})}
 for(let i=0;i<8;i++){let x=rand()*WORLD,y=rand()*WORLD;zombies.push({x,y,r:9,type:'infected',hp:2,state:'wander',dir:rand()*TAU,speed:29,attack:0,stun:0,wander:0,alert:0})}return regions}
const regions=makeWorld();inventory.push({name:'Rag',qty:2},{name:'Trail mix',qty:1});
function addItem(name,qty=1){let item=inventory.find(i=>i.name===name);if(item)item.qty+=qty;else inventory.push({name,qty})}function countItem(name){const it=inventory.find(i=>i.name===name);return it?it.qty:0}function removeItem(name,qty=1){const it=inventory.find(i=>i.name===name);if(!it||it.qty<qty)return false;it.qty-=qty;if(!it.qty)inventory.splice(inventory.indexOf(it),1);return true}function weight(){return inventory.reduce((n,it)=>n+(items[it.name]?.weight||1)*it.qty,0)}
