 const near=nearestThing(),prompt=$('prompt');if(near&&near.d<55){prompt.textContent=near.kind==='loot'?'[ E ] PICK UP '+near.ref.name.toUpperCase():near.kind==='building'?'[ E ] SEARCH '+near.ref.name.toUpperCase():'';prompt.classList.toggle('show',!!prompt.textContent)}else prompt.classList.remove('show');const threat=zombies.some(z=>z.hp>0&&dist(player,z)<150);$('threatIndicator').classList.toggle('show',threat);['Trail mix','Purified water','Bandage'].forEach((name,i)=>{const q=$(('slot'+i));if(q)q.textContent=name+' ×'+countItem(name)});$('regionLabel').textContent='NORTH CASCADE · '+$('dayText').textContent;
}
function nearbyZombie(max=48){let best=null,bd=max;for(const z of zombies){const d=dist(player,z);if(z.hp>0&&d<bd){best=z;bd=d}}return best}
function interact(){const n=nearestThing();if(!n||n.d>55){toast('Nothing nearby to interact with');return}if(n.kind==='loot'){if(weight()+items[n.ref.name].weight>capacity){toast('Pack is full — discard something');return}n.ref.active=false;addItem(n.ref.name);toast('Picked up '+n.ref.name);return}if(n.kind==='building'){if(n.ref.searched){toast('Nothing else here');return}n.ref.searched=true;const drops=1+Math.floor(rand()*2);for(let i=0;i<drops;i++){const pool=Object.keys(items).filter(k=>['home','any'].includes(items[k].loot));const name=choose(pool);if(weight()+items[name].weight<=capacity)addItem(name)}toast('Searched '+n.ref.name+' · supplies found');return}attack()}
