/* =========================================================
   AFTERLIGHT — interface
   ========================================================= */
*{box-sizing:border-box}
:root{
  --ink:#e9e8da;--muted:#98a191;--dim:#68725f;
  --line:rgba(214,222,199,.14);--line-soft:rgba(214,222,199,.08);
  --panel:rgba(14,20,15,.82);--panel-solid:#111812;--deep:#0b100c;
  --lime:#c3d18c;--amber:#d9b477;--red:#d07a66;--blue:#84aeb1;--rust:#a87654;
  --mono:'DM Mono',ui-monospace,monospace;--sans:'DM Sans',system-ui,sans-serif;
  --serif:'Oswald',sans-serif;
}
html,body{margin:0;height:100%;width:100%;overflow:hidden;background:var(--deep);color:var(--ink);font-family:var(--sans);-webkit-tap-highlight-color:transparent}
body{overscroll-behavior:none}
button{font:inherit;color:inherit;background:none;border:none;cursor:pointer}
canvas{display:block}
#app{position:fixed;inset:0;overflow:hidden}
#game{position:absolute;inset:0;width:100%;height:100%;touch-action:none;background:#1b241a}
#vignette{position:absolute;inset:0;pointer-events:none;z-index:1;background:radial-gradient(ellipse at 50% 52%,transparent 38%,rgba(5,9,6,.28) 100%)}
#damageFlash{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:0;background:radial-gradient(ellipse at 50% 50%,transparent 32%,rgba(122,24,18,.55) 100%);transition:opacity .25s}
#lowHealth{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:0;background:radial-gradient(ellipse at 50% 50%,transparent 46%,rgba(86,12,10,.42) 100%);animation:pulse 2.4s infinite}
@keyframes pulse{0%,100%{opacity:.35}50%{opacity:.72}}

/* ---------- top bar ---------- */
#topbar{position:absolute;top:0;left:0;right:0;height:62px;z-index:6;display:flex;align-items:center;gap:20px;padding:0 20px;
  background:linear-gradient(180deg,rgba(9,14,10,.92),rgba(9,14,10,.55) 74%,transparent);pointer-events:none}
#topbar>*{pointer-events:auto}
.brand{display:flex;align-items:center;gap:9px;font-family:var(--serif);letter-spacing:2.2px;font-size:17px;font-weight:500;flex-shrink:0}
.brand-mark{width:25px;height:25px;display:grid;place-items:center;border:1px solid #8b9874;color:#cbd79a;font-family:Georgia,serif;font-size:16px;transform:rotate(45deg)}
.brand-word span{color:#84926f}
.location-block{display:grid;gap:2px;line-height:1.1;min-width:0;padding-left:4px}
.eyebrow{font:8px/1.4 var(--mono);letter-spacing:1.7px;color:#9aa78b}
.location-block strong{font:14px var(--serif);letter-spacing:1.4px;font-weight:400;color:#e6e7d9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.compass{flex:1;max-width:330px;margin-left:auto;display:flex;flex-direction:column;align-items:center;gap:3px;min-width:0}
.compass-window{width:100%;height:24px;overflow:hidden;position:relative;mask-image:linear-gradient(90deg,transparent,#000 18%,#000 82%,transparent)}
.compass-ticks{position:absolute;top:0;left:0;height:100%;display:flex;align-items:flex-start;gap:0;will-change:transform}
.compass-ticks span{flex:0 0 46px;text-align:center;font:9px var(--mono);letter-spacing:1px;color:#a9b29b;position:relative;padding-top:2px}
.compass-ticks span.major{color:#e6e7d9;font-size:10px}
.compass-ticks span::after{content:'';position:absolute;left:50%;bottom:0;width:1px;height:5px;background:rgba(214,222,199,.28)}
.compass-ticks span.major::after{height:9px;background:var(--lime)}
.compass-heading{font:9px var(--mono);letter-spacing:1.6px;color:#98a48b}
.env-block{display:flex;align-items:center;gap:16px;flex-shrink:0}
.clock{display:grid;text-align:right;line-height:1.15}
.clock strong{font:15px var(--mono);letter-spacing:1px;font-weight:500}
.clock span{font:8px var(--mono);letter-spacing:1.4px;color:#98a48b}
.weather{display:flex;align-items:center;gap:6px}
.weather>span{font-size:19px;color:var(--amber);line-height:1}
.weather div{display:grid;line-height:1.2}
.weather strong{font:9px var(--mono);letter-spacing:1.2px;font-weight:500;color:#c9cfba}
.weather small{font:9px var(--mono);color:#8b9784}
.top-actions{display:flex;gap:5px;flex-shrink:0}
.icon-btn{height:32px;min-width:34px;padding:0 8px;border:1px solid var(--line);border-radius:3px;color:#c3cbbb;
  font:14px var(--mono);display:flex;align-items:center;justify-content:center;gap:5px;background:rgba(16,23,17,.55);transition:.15s}
.icon-btn span{font:8px var(--mono);letter-spacing:1px;color:#a9b39b}
.icon-btn:hover{border-color:#a9b681;background:rgba(195,209,140,.1);color:#eef2e2}
.icon-btn:active{transform:scale(.95)}

/* ---------- vitals ---------- */
#vitals{position:absolute;left:18px;bottom:18px;z-index:5;width:196px;padding:12px 13px;display:grid;gap:8px;
  background:linear-gradient(150deg,rgba(15,22,16,.9),rgba(12,18,13,.76));border:1px solid var(--line);border-radius:4px;backdrop-filter:blur(7px)}
.vital{display:grid;gap:4px}
.vital-top{display:flex;align-items:baseline;justify-content:space-between;font:8px var(--mono);letter-spacing:1.2px;color:#98a190}
.vital-top b{font:9px var(--mono);font-weight:500;color:#dde2d1;letter-spacing:.5px}
.bar{height:4px;background:rgba(214,222,199,.12);border-radius:3px;overflow:hidden}
.bar i{display:block;height:100%;width:100%;background:var(--lime);transition:width .35s ease,background .35s}
.vital.health .bar i{background:linear-gradient(90deg,#a6bd78,#d1dc9e)}
.vital.blood .bar i{background:linear-gradient(90deg,#a3564a,#cf8272)}
.vital.food .bar i{background:linear-gradient(90deg,#b09a63,#d9c08a)}
.vital.water .bar i{background:linear-gradient(90deg,#6d979b,#95c3c4)}
.vital.temp .bar i{background:linear-gradient(90deg,#b38157,#d9b477)}
.vital.stamina .bar i{background:linear-gradient(90deg,#7f9583,#a8c0ac)}
.vital.energy .bar i{background:linear-gradient(90deg,#9d8fa8,#c9b6d1)}
.conditions{display:flex;flex-wrap:wrap;gap:4px;min-height:0}
.conditions:empty{display:none}
.chip{font:7.5px var(--mono);letter-spacing:.8px;padding:3px 5px;border:1px solid rgba(208,122,102,.4);color:#e0a797;background:rgba(208,122,102,.12);border-radius:2px}
.chip.cold{border-color:rgba(132,174,177,.4);color:#b6d6d8;background:rgba(132,174,177,.12)}
.chip.good{border-color:rgba(195,209,140,.4);color:#dae4b6;background:rgba(195,209,140,.1)}
.chip.warn{border-color:rgba(217,180,119,.4);color:#e6cd9f;background:rgba(217,180,119,.12)}

/* ---------- gear / bottom right ---------- */
#gear{position:absolute;right:18px;bottom:18px;z-index:5;width:238px;display:grid;gap:7px}
.gear-row{display:flex;align-items:flex-end;gap:8px;justify-content:flex-end}
.weapon-card{flex:1;padding:8px 11px;background:var(--panel);border:1px solid var(--line);border-radius:4px;backdrop-filter:blur(7px);min-width:0}
.weapon-card strong{display:block;font:13px var(--serif);letter-spacing:1.1px;font-weight:400;margin:3px 0 3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.weapon-meta{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:.8px;color:#a5ae9b}
.weapon-meta span:last-child{color:#8fa07c}
.quick-slots{display:flex;gap:4px}
.quick{width:42px;height:42px;border:1px solid var(--line);background:rgba(16,23,17,.8);border-radius:3px;position:relative;padding:3px;
  font:7px var(--mono);color:#cfd5c2;overflow:hidden;text-align:left}
.quick kbd{position:absolute;top:2px;left:3px;font:7px var(--mono);color:#8f9b84}
.quick span{display:block;margin-top:12px;line-height:1.15;max-height:20px;overflow:hidden}
.quick.active{border-color:var(--lime);box-shadow:0 0 0 1px rgba(195,209,140,.25) inset}
.status-line{display:flex;gap:10px;justify-content:flex-end;font:8px var(--mono);letter-spacing:1px;color:#8b9784}
.status-line span:first-child{color:#c3cbb8}

/* ---------- center hud ---------- */
#crosshair{position:absolute;left:50%;top:50%;z-index:4;transform:translate(-50%,-50%);pointer-events:none;opacity:.85;transition:opacity .15s}
#crosshair i{display:block;width:4px;height:4px;border-radius:50%;background:rgba(240,243,226,.9);box-shadow:0 0 5px rgba(0,0,0,.6)}
#crosshair b{position:absolute;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);border:1px solid rgba(230,235,214,.32);border-radius:50%;transition:.2s}
#crosshair.ads b{width:14px;height:14px;border-color:rgba(240,243,226,.6)}
#crosshair.hidden{opacity:0}
#hitmarker{position:absolute;left:50%;top:50%;z-index:4;width:22px;height:22px;transform:translate(-50%,-50%) rotate(45deg);opacity:0;pointer-events:none}
#hitmarker::before,#hitmarker::after{content:'';position:absolute;background:#f3e9c9}
#hitmarker::before{left:50%;top:0;width:1px;height:100%;transform:translateX(-50%)}
#hitmarker::after{top:50%;left:0;height:1px;width:100%;transform:translateY(-50%)}
#hitmarker.show{animation:hit .28s ease-out}
@keyframes hit{0%{opacity:1;transform:translate(-50%,-50%) rotate(45deg) scale(.7)}100%{opacity:0;transform:translate(-50%,-50%) rotate(45deg) scale(1.35)}}
#threat{position:absolute;top:82px;left:50%;transform:translateX(-50%);z-index:4;font:9px var(--mono);letter-spacing:2px;color:#e2a596;
  padding:5px 10px;border:1px solid rgba(208,122,102,.35);border-radius:2px;background:rgba(53,20,16,.5);opacity:0;transition:.3s;pointer-events:none}
#threat span{display:inline-block;width:5px;height:5px;border-radius:50%;background:#d07a66;margin-right:6px;animation:pulse 1.2s infinite}
#threat.show{opacity:1}
#prompt{position:absolute;left:50%;bottom:120px;transform:translateX(-50%);z-index:4;display:none;align-items:center;gap:8px;padding:8px 12px;
  background:rgba(11,17,12,.85);border:1px solid var(--line);border-radius:3px;font:10px var(--mono);letter-spacing:.8px;color:#e2e6d5;backdrop-filter:blur(6px);white-space:nowrap}
#prompt.show{display:flex}
#prompt kbd{font:9px var(--mono);padding:2px 5px;border:1px solid rgba(195,209,140,.5);color:var(--lime);border-radius:2px}
#toasts{position:absolute;top:78px;left:50%;transform:translateX(-50%);z-index:7;display:grid;gap:6px;justify-items:center;pointer-events:none;width:min(420px,86vw)}
.toast{padding:7px 12px;background:rgba(12,19,13,.9);border:1px solid var(--line);border-left:2px solid var(--lime);border-radius:2px;
  font:9.5px var(--mono);letter-spacing:.5px;color:#dde2cf;animation:toastIn .25s ease,toastOut .4s ease 2.9s forwards;max-width:100%;text-align:center}
.toast.bad{border-left-color:var(--red);color:#ecc2b7}
.toast.warn{border-left-color:var(--amber);color:#ecd7ae}
@keyframes toastIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateY(-4px)}}

#objective{position:absolute;left:18px;bottom:262px;z-index:4;display:flex;align-items:center;gap:9px;padding:8px 10px;max-width:270px;
  background:rgba(12,18,13,.68);border:1px solid var(--line-soft);border-radius:3px;backdrop-filter:blur(5px)}
.obj-pin{color:var(--lime);font-size:13px}
#objective div{display:grid;gap:2px;min-width:0}
#objective small{font:7px var(--mono);letter-spacing:1.4px;color:#93a084}
#objective span{font:9.5px/1.35 var(--sans);color:#d5dacb}
#objective button{color:#8b9784;font-size:14px;padding:2px 4px;align-self:stretch}
#objective.hide{display:none}

/* ---------- mobile controls ---------- */
#mobileControls{position:absolute;inset:0;z-index:5;display:none;pointer-events:none}
.joystick{position:absolute;left:20px;bottom:22px;width:118px;height:118px;border-radius:50%;pointer-events:auto;touch-action:none;
  background:radial-gradient(circle,rgba(18,26,19,.5),rgba(12,18,13,.28));border:1px solid rgba(214,222,199,.18)}
.joystick-ring{position:absolute;inset:22px;border-radius:50%;border:1px solid rgba(214,222,199,.12)}
.joy-knob{position:absolute;left:50%;top:50%;width:44px;height:44px;margin:-22px;border-radius:50%;
  background:rgba(195,209,140,.22);border:1px solid rgba(220,228,204,.4);box-shadow:0 4px 14px rgba(0,0,0,.35)}
.look-hint{position:absolute;right:26px;top:96px;font:8px var(--mono);letter-spacing:1.4px;color:rgba(222,227,211,.5);pointer-events:none}
.touch-cluster{position:absolute;right:14px;bottom:20px;width:178px;height:178px;pointer-events:none}
.tbtn{position:absolute;border-radius:50%;border:1px solid rgba(219,226,205,.28);background:rgba(14,21,15,.62);color:#e1e6d4;
  font:9px var(--mono);letter-spacing:.8px;pointer-events:auto;touch-action:none;backdrop-filter:blur(4px);display:grid;place-items:center}
.tbtn:active{background:rgba(195,209,140,.22)}
.tbtn.attack{width:74px;height:74px;right:2px;bottom:14px;font-size:12px;color:#f0b9a8;border-color:rgba(224,144,120,.45);background:rgba(48,23,18,.6)}
.tbtn.use{width:58px;height:58px;right:84px;bottom:66px;font-size:10px;color:#dce6c0;border-color:rgba(195,209,140,.42);background:rgba(27,36,22,.62)}
.tbtn.small{width:38px;height:38px;font-size:13px;color:#c3cbb8}
#btnAim{right:92px;bottom:12px}
#btnReload{right:24px;bottom:96px}
#btnJump{right:68px;bottom:112px}
#btnCrouch{right:112px;bottom:92px}
#btnTorch{right:146px;bottom:38px}
#btnBuild{right:144px;bottom:96px}

/* ---------- overlay + modals ---------- */
#overlay{position:fixed;inset:0;z-index:30;background:rgba(5,9,6,.72);backdrop-filter:blur(7px);display:grid;place-items:center;padding:18px;animation:fade .18s}
#overlay[hidden]{display:none}
@keyframes fade{from{opacity:0}to{opacity:1}}
#modal{width:min(780px,96vw);max-height:90dvh;overflow:auto;background:linear-gradient(160deg,#151c16,#101610);border:1px solid rgba(214,222,199,.18);
  box-shadow:0 30px 90px rgba(0,0,0,.6);padding:22px 24px 24px;position:relative;scrollbar-width:thin;scrollbar-color:#4a5442 transparent}
#modal::-webkit-scrollbar{width:8px}
#modal::-webkit-scrollbar-thumb{background:#39422f;border-radius:4px}
.modal-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;border-bottom:1px solid var(--line-soft);padding-bottom:14px;margin-bottom:16px}
.modal-head h2{font:24px var(--serif);font-weight:400;letter-spacing:1px;margin:4px 0 0}
.modal-head .close{width:30px;height:30px;border:1px solid var(--line);color:#a9b29d;font-size:17px;line-height:1;flex-shrink:0}
.modal-head .close:hover{border-color:#aab67f;color:#eef1e0}
.modal-sub{font:9px var(--mono);letter-spacing:.6px;color:#93a084;margin-top:4px}
.modal-foot{font:9px/1.6 var(--mono);letter-spacing:.3px;color:#86927e;margin-top:16px;border-top:1px solid var(--line-soft);padding-top:10px}
.modal-foot kbd,.help-grid kbd{font:9px var(--mono);border:1px solid rgba(214,222,199,.24);padding:2px 4px;color:#dfe4d3;border-radius:2px}
.sec-title{display:flex;justify-content:space-between;align-items:baseline;margin:16px 0 8px}
.sec-title h3{font:11px var(--mono);letter-spacing:1.6px;color:#aab59a;font-weight:400;margin:0}
.sec-title span{font:8px var(--mono);color:#7f8b78}

/* inventory */
.equip-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-bottom:6px}
.equip-slot{padding:8px;background:#182018;border:1px solid var(--line-soft);border-radius:3px;min-height:58px}
.equip-slot small{display:block;font:7px var(--mono);letter-spacing:1.1px;color:#8d9a83;margin-bottom:5px}
.equip-slot strong{display:block;font:10px/1.25 var(--sans);color:#d9dfcd;overflow:hidden;text-overflow:ellipsis}
.equip-slot span{display:block;font:8px var(--mono);color:#8fa07c;margin-top:3px}
.inv-list{display:grid;gap:5px}
.inv-row{display:flex;align-items:center;gap:8px;padding:7px 8px;background:#1a221a;border:1px solid var(--line-soft);border-radius:2px}
.inv-row:hover{border-color:rgba(195,209,140,.24)}
.inv-icon{width:28px;height:28px;display:grid;place-items:center;background:#283324;color:#cad69a;font-size:14px;border-radius:2px;flex-shrink:0}
.inv-main{flex:1;min-width:0}
.inv-main strong{display:block;font:10.5px var(--sans);color:#e0e5d4;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.inv-main small{display:block;font:7.5px var(--mono);letter-spacing:.4px;color:#8b9780;margin-top:2px}
.cond-pill{font:7px var(--mono);padding:2px 4px;border-radius:2px;border:1px solid rgba(195,209,140,.3);color:#c6d39a;flex-shrink:0}
.cond-pill.low{border-color:rgba(217,180,119,.4);color:#e0c38e}
.cond-pill.bad{border-color:rgba(208,122,102,.4);color:#e5a998}
.inv-actions{display:flex;gap:4px;flex-shrink:0}
