/* ------------------------------------------------------------
   Terrain, water, forest instancing
   ------------------------------------------------------------ */
let treeTrunkMesh = null, treeFoliageMesh = null;

function buildTerrain() {
  const geo = new THREE.PlaneGeometry(WORLD, WORLD, 150, 150);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    pos.setY(i, heightAt(x, z));
  }
  geo.computeVertexNormals();
  const tex = makeGroundTexture();
  const mat = new THREE.MeshStandardMaterial({ map: tex, roughness: 1, metalness: 0 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = false;
  sceneRoot.add(mesh);

  // lake surface
  for (const l of lakes) {
    const lakeMesh = new THREE.Mesh(new THREE.CircleGeometry(1, 56), new THREE.MeshStandardMaterial({
      color: 0x375f60, roughness: 0.22, metalness: 0.25, transparent: true, opacity: 0.92,
    }));
    lakeMesh.rotation.x = -Math.PI / 2;
    lakeMesh.scale.set(l.rx * 1.02, l.rz * 1.02, 1);
    lakeMesh.position.set(l.x, WATER_LEVEL, l.z);
    sceneRoot.add(lakeMesh);
  }
  // river ribbon
  for (const r of rivers) {
    const pts = [];
    for (let z = -HALF + 4; z <= HALF - 4; z += 12) pts.push(riverPoint(r, z));
    const verts = [], idx = [];
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i];
      verts.push(p.x - r.half, WATER_LEVEL, p.z, p.x + r.half, WATER_LEVEL, p.z);
    }
    for (let i = 0; i < pts.length - 1; i++) {
      const a = i * 2;
      idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    const mesh = new THREE.Mesh(g, new THREE.MeshStandardMaterial({
      color: 0x3b6162, roughness: 0.25, metalness: 0.2, transparent: true, opacity: 0.94,
    }));
    sceneRoot.add(mesh);
  }
  return mesh;
}

function buildForest() {
  const forestPts = [];
  const avoid = (x, z) => {
    for (const s of settlements) if (Math.hypot(x - s.x, z - s.z) < s.r * 1.35) return true;
    for (const b of buildings) if (Math.abs(x - b.x) < b.w * 0.8 + 3 && Math.abs(z - b.z) < b.d * 0.8 + 3) return true;
    if (waterMask(x, z) > 0.06) return true;
    if (nearWater(x, z, 6)) return true;
    return false;
  };
  let guard = 0;
  while (forestPts.length < 560 && guard < 12000) {
    guard++;
    const x = (rand() - 0.5) * (WORLD - 70);
    const z = (rand() - 0.5) * (WORLD - 70);
    if (avoid(x, z)) continue;
    const edge = Math.max(Math.abs(x), Math.abs(z));
    if (edge > 760 && rand() < 0.75) continue;
    forestPts.push({ x, z, s: 0.7 + rand() * 0.8, pine: rand() < 0.78 });
  }

  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.32, 4.4, 6);
  trunkGeo.translate(0, 2.2, 0);
  const folGeo = new THREE.ConeGeometry(1.7, 4.4, 7);
  folGeo.translate(0, 4.4, 0);
  treeTrunkMesh = new THREE.InstancedMesh(trunkGeo, M.trunk, forestPts.length);
  treeFoliageMesh = new THREE.InstancedMesh(folGeo, M.pine, forestPts.length);
  treeFoliageMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(forestPts.length * 3), 3);
  const mtx = new THREE.Matrix4();
  const col = new THREE.Color();
  forestPts.forEach((t, i) => {
    const y = heightAt(t.x, t.z);
    mtx.makeScale(t.s, t.s, t.s);
    mtx.setPosition(t.x, y, t.z);
    treeTrunkMesh.setMatrixAt(i, mtx);
    treeFoliageMesh.setMatrixAt(i, mtx);
    col.setHex(t.pine ? (rand() < 0.5 ? 0x2c4530 : 0x355038) : 0x445b36);
    treeFoliageMesh.setColorAt(i, col);
    const tree = { x: t.x, z: t.z, s: t.s, r: 0.55 * t.s, i, chopped: 0, felled: false, type: t.pine ? 'pine' : 'oak' };
    trees.push(tree);
    circleColliders.push({ x: t.x, z: t.z, r: 0.5 * t.s, type: 'tree', tree });
  });
  treeTrunkMesh.instanceMatrix.needsUpdate = true;
  treeFoliageMesh.instanceMatrix.needsUpdate = true;
  sceneRoot.add(treeTrunkMesh, treeFoliageMesh);

  // bushes
  const bushGeo = new THREE.IcosahedronGeometry(1, 0);
  const bushMesh = new THREE.InstancedMesh(bushGeo, M.leaf, 300);
  const q = new THREE.Quaternion(), v = new THREE.Vector3(), sc = new THREE.Vector3();
  for (let i = 0; i < 300; i++) {
    let x, z, ok = false;
    for (let k = 0; k < 20 && !ok; k++) {
      x = (rand() - 0.5) * (WORLD - 80); z = (rand() - 0.5) * (WORLD - 80);
      ok = !avoid(x, z);
    }
    if (!ok) { x = 0; z = 0; }
    const s = 0.5 + rand() * 1.1;
    v.set(x, heightAt(x, z) + s * 0.5, z);
    sc.set(s * 1.3, s * 0.8, s * 1.3);
    mtx.compose(v, q, sc);
    bushMesh.setMatrixAt(i, mtx);
  }
  bushMesh.instanceMatrix.needsUpdate = true;
  sceneRoot.add(bushMesh);

  // rocks
  const rockGeo = new THREE.DodecahedronGeometry(1, 0);
  const rockMesh = new THREE.InstancedMesh(rockGeo, M.rock, 120);
  for (let i = 0; i < 120; i++) {
    const x = (rand() - 0.5) * (WORLD - 60), z = (rand() - 0.5) * (WORLD - 60);
    const s = 0.5 + rand() * 2.0;
    v.set(x, heightAt(x, z) + s * 0.25, z);
    sc.set(s, s * 0.7, s);
    q.setFromEuler(new THREE.Euler(0, rand() * Math.PI, 0));
    mtx.compose(v, q, sc);
    rockMesh.setMatrixAt(i, mtx);
    if (s > 1.0) circleColliders.push({ x, z, r: s * 0.8 });
  }
  rockMesh.instanceMatrix.needsUpdate = true;
  sceneRoot.add(rockMesh);
}

export function hideTree(tree) {
  if (!tree || tree.felled) return;
  tree.felled = true;
  const mtx = new THREE.Matrix4();
  mtx.makeScale(0, 0, 0);
  treeTrunkMesh.setMatrixAt(tree.i, mtx);
  treeFoliageMesh.setMatrixAt(tree.i, mtx);
  treeTrunkMesh.instanceMatrix.needsUpdate = true;
  treeFoliageMesh.instanceMatrix.needsUpdate = true;
}

/* ------------------------------------------------------------
   Loot containers (visuals)
   ------------------------------------------------------------ */
const TIER_COLORS = {
  residential: 0x7a6847, store: 0x8b7a50, supermarket: 0x9a8658, medical: 0xb9b6a4,
  police: 0x3f4f5c, military: 0x4c5a3d, industrial: 0x6a6a5f, farm: 0x77603f,
  hunting: 0x5c6144, camp: 0x67704f,
};

function buildContainers() {
  for (const c of containers) {
    const baseY = c.y ?? heightAt(c.x, c.z);
    let mesh;
    if (c.type === 'duffel') {
      const g = new THREE.Group();
      const mat = new THREE.MeshStandardMaterial({ color: TIER_COLORS[c.tier] || 0x6c7052, roughness: 0.95, emissive: 0x000000 });
      const bag = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.55, 0.52), mat);
      bag.position.y = 0.28; g.add(bag);
      const strap = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.035, 5, 12, Math.PI), M.woodDark);
      strap.rotation.x = Math.PI / 2; strap.position.y = 0.56; g.add(strap);
      g.position.set(c.x, baseY, c.z); g.rotation.y = rand() * Math.PI;
      mesh = g; c.mat = mat;
    } else if (c.type === 'barrel') {
      const mat = new THREE.MeshStandardMaterial({ color: TIER_COLORS[c.tier] || 0x6a6a5f, roughness: 0.8, metalness: 0.25, emissive: 0x000000 });
      mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.4, 0.95, 9), mat);
      mesh.position.set(c.x, baseY + 0.48, c.z);
      c.mat = mat;
    } else {
      const g = new THREE.Group();
      const mat = new THREE.MeshStandardMaterial({ color: TIER_COLORS[c.tier] || 0x7a6847, roughness: 0.9, emissive: 0x000000 });
      const body = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.58, 0.72), mat);
      body.position.y = 0.35; g.add(body);
      const lid = new THREE.Mesh(new THREE.BoxGeometry(1.09, 0.12, 0.76), M.woodDark);
      lid.position.y = 0.66; g.add(lid);
      for (const sx of [-0.36, 0.36]) {
        const strap = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.62, 0.76), M.metal);
        strap.position.set(sx, 0.37, 0); g.add(strap);
      }
      g.position.set(c.x, baseY, c.z); g.rotation.y = rand() * Math.PI;
      mesh = g; c.mat = mat;
    }
    // small marker so loot is findable in the dark
    const glintMat = new THREE.MeshBasicMaterial({ color: c.tier === 'military' ? 0xd8cf9a : 0xf0e3b2, transparent: true, opacity: 0.85 });
    const glint = new THREE.Mesh(new THREE.OctahedronGeometry(0.075, 0), glintMat);
    glint.position.set(c.x, baseY + 1.05, c.z);
    glint.userData.base = baseY + 1.05;
    sceneRoot.add(glint);
    c.glint = glint;
    c.mesh = mesh;
    sceneRoot.add(mesh);
  }
}

export function updateContainerGlints(dt, t) {
  for (const c of containers) {
    if (!c.glint) continue;
    c.glint.visible = !c.searched;
    if (c.searched) continue;
    c.glint.rotation.y += dt * 1.5;
    c.glint.position.y = c.glint.userData.base + Math.sin(t * 2 + c.x) * 0.05;
  }
}

/* ------------------------------------------------------------
   World assembly
   ------------------------------------------------------------ */
export function buildWorld(scene) {
  sceneRoot = new THREE.Group();
  scene.add(sceneRoot);
  buildTerrain();
  layoutWorld();
  buildForest();
  buildContainers();
  return sceneRoot;
}

export function nearestContainer(x, z, radius = 2.6) {
  let best = null, bd = radius;
  for (const c of containers) {
    if (c.searched) continue;
    const d = Math.hypot(c.x - x, c.z - z);
    if (d < bd) { bd = d; best = c; }
  }
  return best;
}

export function nearestTree(x, z, radius = 2.8) {
  let best = null, bd = radius;
  for (const t of trees) {
    if (t.felled) continue;
    const d = Math.hypot(t.x - x, t.z - z);
    if (d < bd) { bd = d; best = t; }
  }
  return best;
}

export function nearestDoor(x, z, radius = 2.6) {
  let best = null, bd = radius;
  for (const d of doors) {
    const dd = Math.hypot(d.x - x, d.z - z);
    if (dd < bd) { bd = dd; best = d; }
  }
  return best;
}

/* ------------------------------------------------------------
   Audio (synthesised — no external assets)
   ------------------------------------------------------------ */
const audio = {
  ctx: null, master: null, wind: null, rain: null, fire: null,

  init() {
    if (this.ctx) { this.ctx.resume?.(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const ctx = this.ctx = new AC();
      this.master = ctx.createGain();
      this.master.gain.value = 0.55;
      this.master.connect(ctx.destination);
      const len = ctx.sampleRate * 2;
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;

      const wind = ctx.createBufferSource(); wind.buffer = buf; wind.loop = true;
      const windF = ctx.createBiquadFilter(); windF.type = 'lowpass'; windF.frequency.value = 420;
      const windG = ctx.createGain(); windG.gain.value = 0.1;
      wind.connect(windF).connect(windG).connect(this.master); wind.start();
      this.wind = windG; this.windFilter = windF;

      const rain = ctx.createBufferSource(); rain.buffer = buf; rain.loop = true;
      const rainF = ctx.createBiquadFilter(); rainF.type = 'highpass'; rainF.frequency.value = 1100;
      const rainG = ctx.createGain(); rainG.gain.value = 0;
      rain.connect(rainF).connect(rainG).connect(this.master); rain.start();
      this.rain = rainG;

      const fire = ctx.createBufferSource(); fire.buffer = buf; fire.loop = true;
      const fireF = ctx.createBiquadFilter(); fireF.type = 'bandpass'; fireF.frequency.value = 2400; fireF.Q.value = 0.7;
      const fireG = ctx.createGain(); fireG.gain.value = 0;
      fire.connect(fireF).connect(fireG).connect(this.master); fire.start();
      this.fire = fireG;
      state.audioReady = true;
    } catch (e) { console.warn('audio unavailable', e); }
  },

  burst(dur, freq, gain, type = 'lowpass', q = 0.7) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t); src.stop(t + dur + 0.05);
  },

  tone(freq, dur, gain, type = 'sine', slide = 0) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master); o.start(t); o.stop(t + dur + 0.03);
  },

  shot(kind) {
    if (!this.ctx) return;
    this.burst(0.3, kind === 'shotgun' ? 700 : 1500, 0.5);
    this.burst(0.55, 180, 0.3, 'lowpass');
    this.tone(kind === 'rifle' ? 90 : 120, 0.22, 0.3, 'triangle', -50);
  },
  swing() { this.burst(0.13, 900, 0.12, 'bandpass', 1.2); },
  hit() { this.burst(0.12, 380, 0.22, 'lowpass'); this.tone(70, 0.12, 0.2, 'sine'); },
  hurt() { this.burst(0.25, 260, 0.3); this.tone(58, 0.35, 0.16, 'sine'); },
  pickup() { this.tone(520, 0.08, 0.06, 'triangle'); this.tone(760, 0.1, 0.045, 'triangle'); },
  ui() { this.tone(420, 0.045, 0.035, 'square'); },
  step(surface) {
    const f = surface === 'water' ? 700 : surface === 'wood' ? 500 : surface === 'gravel' ? 900 : 380;
    this.burst(0.05, f, 0.05 + player.noise * 0.05, 'bandpass', 1.5);
  },
  growl(vol = 0.2) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(), g = ctx.createGain(), f = ctx.createBiquadFilter();
    o.type = 'sawtooth'; o.frequency.setValueAtTime(72 + rand() * 26, t);
    o.frequency.linearRampToValueAtTime(52 + rand() * 16, t + 0.7);
    f.type = 'lowpass'; f.frequency.value = 480;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.12);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.9);
    o.connect(f).connect(g).connect(this.master);
    o.start(t); o.stop(t + 1);
  },
  scream(vol = 0.25) {
    this.tone(360, 0.5, vol, 'sawtooth', -180);
    this.burst(0.5, 900, vol * 0.4, 'bandpass', 2);
  },
  thunder() {
    this.burst(2.4, 120, 0.35, 'lowpass');
    this.tone(42, 2.0, 0.14, 'sine', -12);
  },
  heartbeat() { this.tone(48, 0.16, 0.22, 'sine', -8); },
  reload() { this.burst(0.08, 2000, 0.09, 'highpass', 2); },
  eat() { this.burst(0.2, 700, 0.12, 'bandpass', 1.2); },
  drink() { this.tone(360, 0.22, 0.08, 'sine', 80); },
  craft() { this.burst(0.12, 900, 0.1, 'bandpass'); this.tone(320, 0.2, 0.05, 'triangle'); },
};

