function startBuild(type) {
  if (!BUILDS[type]) return;
  if (!canAfford(BUILDS[type].cost)) { toast('Missing materials for ' + BUILDS[type].name, 'warn'); return; }
  closeModal();
  setBuildMode(true, type);
}

