function mergeStaticBoxes() {
  const groups = new Map();
  const toRemove = [];
  sceneRoot.children.forEach(m => {
    if (!m.isMesh || !m.geometry || m.geometry.type!=='BoxGeometry') return;
    const key = m.material.uuid;
    if (!groups.has(key)) groups.set(key, {mat:m.material, meshes:[]});
    groups.get(key).meshes.push(m);
  });
  for (const {mat, meshes} of groups.values()) {
    if (meshes.length < 2) continue;
    const positions=[], normals=[], uvs=[], indices=[];
    let offset=0;
    for (const m of meshes) {
      m.updateMatrixWorld(true);
      const g = m.geometry; const pos = g.attributes.position; const norm=g.attributes.normal; const uv=g.attributes.uv; const idx=g.index;
      const nm = new THREE.Matrix3().getNormalMatrix(m.matrixWorld);
      const v=new THREE.Vector3();
      for (i<pos.count) { v.fromBufferAttribute(pos,i).applyMatrix4(m.matrixWorld); positions.push(...); v.fromBufferAttribute(norm,i).applyMatrix3(nm).normalize(); normals.push(); if(uv) uvs.push(uv.getX(i),uv.getY(i)); }
      if (idx) for each indices.push(idx.getX(i)+offset); else for i push i+offset;
      offset += pos.count;
    }
    const geo = new BufferGeometry(); set attrs; setIndex; computeBoundingSphere;
    const merged = new Mesh(geo, mat); merged.frustumCulled=true; sceneRoot.add(merged);
    meshes.forEach(m=>{ sceneRoot.remove(m); toRemove.push(m); });
  }
}
